local BOOST_SPEED = 100local BOOST_DURATION = 1.2local FINAL_SPEED = 23local ReplicatedStorage = game:GetService("ReplicatedStorage")local Players = game:GetService("Players")local RunService = game:GetService("RunService")local player = Players.LocalPlayerlocal folder = ReplicatedStorage["events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"]if not folder then return end-- Find all RemoteEvent children inside the folderlocal remotes = {}for _, child in ipairs(folder:GetChildren()) do    if child:IsA("RemoteEvent") then        table.insert(remotes, child)    endendif #remotes == 0 then return endlocal boostActive = falselocal endTime = 0local heartbeatConnectionlocal function getHumanoid()    local char = player.Character    return char and char:FindFirstChildOfClass("Humanoid")endlocal function applyBoost()    local humanoid = getHumanoid()    if not humanoid then return end    boostActive = true    endTime = tick() + BOOST_DURATION    humanoid.WalkSpeed = BOOST_SPEED    if not heartbeatConnection or not heartbeatConnection.Connected then        heartbeatConnection = RunService.Heartbeat:Connect(function()            local h = getHumanoid()            if not h then return end            if boostActive then                if tick() < endTime then                    h.WalkSpeed = BOOST_SPEED                else                    boostActive = false                    h.WalkSpeed = FINAL_SPEED                    heartbeatConnection:Disconnect()                end            end        end)    endendfor _, remote in ipairs(remotes) do    remote.OnClientEvent:Connect(function(targetModel, action)        if action == "void_axe_jump" then            applyBoost()        end    end)end